package com.bank.patterns;

import java.math.BigDecimal;

// SEALED sum type: the complete, closed set of payment event shapes.
// Each permitted subtype is a RECORD → ideal for record-pattern deconstruction.
public sealed interface PaymentEvent
        permits PaymentEvent.TransferEvent, PaymentEvent.DepositEvent, PaymentEvent.WithdrawalEvent {

    record TransferEvent(String from, String to, BigDecimal amount) implements PaymentEvent { }
    record DepositEvent(String account, BigDecimal amount) implements PaymentEvent { }
    record WithdrawalEvent(String account, BigDecimal amount) implements PaymentEvent { }
}
