package com.bank.patterns;

import com.bank.patterns.PaymentEvent.*;
import java.math.BigDecimal;
import java.util.logging.Logger;

public class PaymentProcessor {
    private static final Logger log = Logger.getLogger(PaymentProcessor.class.getName());
    private static final BigDecimal LARGE = new BigDecimal("100000");

    // Exhaustive pattern-matching switch EXPRESSION over a sealed type.
    // Record patterns deconstruct each event; a `when` guard flags large transfers.
    // NO default is needed → the compiler proves exhaustiveness. Add a 4th subtype
    // to PaymentEvent and THIS METHOD stops compiling until you handle it.
    public String describe(PaymentEvent event) {
        return switch (event) {
            case null ->
                "ignored null event";                        // explicit null handling
            case TransferEvent(String from, String to, BigDecimal amount)
                    when amount.compareTo(LARGE) > 0 ->
                "LARGE transfer Rs." + amount + " " + from + "->" + to + " (flag for review)";
            case TransferEvent(String from, String to, BigDecimal amount) ->
                "transfer Rs." + amount + " " + from + "->" + to;
            case DepositEvent(String account, BigDecimal amount) ->
                "deposit Rs." + amount + " into " + account;
            case WithdrawalEvent(String account, BigDecimal amount) ->
                "withdrawal Rs." + amount + " from " + account;
        };
    }

    public void process(PaymentEvent event) {
        String summary = describe(event);
        log.info(() -> "Processed: " + summary);
    }
}
