package com.bank.patterns;

import com.bank.patterns.PaymentEvent.*;
import java.math.BigDecimal;

public class PatternDemo {
    public static void main(String[] args) {
        PaymentProcessor processor = new PaymentProcessor();

        // Rajesh → Priya normal transfer
        processor.process(new TransferEvent("SAV2001", "CUR3001", new BigDecimal("50000")));
        // Large transfer → hits the guarded case
        processor.process(new TransferEvent("SAV2001", "CUR3001", new BigDecimal("500000")));
        // Deposit into Priya's current account
        processor.process(new DepositEvent("CUR3001", new BigDecimal("25000")));
        // Withdrawal from Rajesh's savings
        processor.process(new WithdrawalEvent("SAV2001", new BigDecimal("10000")));
        // Null is handled explicitly, not with an exception
        processor.process(null);
    }
}
